    @retry(tries=6, delay=3)
    def get_coin_id(self, slug):
        """
        获取代币ID
        """
        url = self.html_url.format(slug)
        logger.info(f'GET: {url}')
        res = requests.get(url, headers=self.headers, proxies=proxies)
        logger.info(f'response: {res.status_code} {url}')
        if res.status_code != 200:
            raise Exception(f'状态码异常 {res.status_code}')
        soup = BeautifulSoup(res.text, 'html.parser')
        target_script = soup.find("script", id="__NEXT_DATA__")
        if target_script:
            # 提取目标script标签的文本内容
            target_script_text = target_script.text
            data = json.loads(target_script_text)
            detail = data['props']['pageProps']['detailRes']['detail']
            coin_id = detail['id']
            return coin_id
        else:
            logger.error(f'无法抽取代币ID：{slug}')
        return


    @retry(tries=6, delay=3)
    def req_one_datecouple_onecoin_vol24(self, url, name):
        """
        获取单个代币，2个月内的vol24小时的数据，
        """
        # url = self.html_url.format(slug)
        logger.info(f'GET: {url}')
        res = requests.get(url, headers=self.headers, proxies=proxies)
        logger.info(f'response: {res.status_code} {url}')
        if res.status_code != 200:
            raise Exception(f'状态码异常 {res.status_code}')
        try:
            data = res.json()['data']
            return data
        except:
            logger.error(f'历史数据解析异常：{name}  {url}')
            # 无法捕获到数据加入错误队列
            self.redis_cli.sadd(self.failed_history_volurl, json.dumps({'name':name, 'url':url}))
            return

    def insert_coin_table(self, name, data):
        """
        将单个代币2个月内的vol24数据插入MYSQL
        """
        category_list = self.jobs[name]['category']
        categories = str(category_list)
        matched_cmc = self.jobs[name]['matched_cmc']
        slug = matched_cmc['slug']
        symbol = matched_cmc['symbol']
        fdv = 0

        # 成功插入的条数 （最理想是2个月60条左右）
        success_inserted_num = 0
        # 把2个月的volume全部插入数据库
        quotes = data['quotes']
        for quote in quotes:
            timeOpen = quote['timeOpen']
            time_date = timeOpen.split('T')[0]
            vol_24h = quote['quote']['volume']
            vol_24h = int(vol_24h)
            spider_time = int(time.time())
            # 通过项目名和日期生成ID
            id = md5(f'{name}{time_date}'.encode()).hexdigest()
            value_sql = f"({repr(id)},{repr(name)},{repr(symbol)},{repr(categories)}," \
                        f"{repr(slug)},{fdv},{vol_24h},{repr(time_date)},{repr(spider_time)},NULL)"
            sql = f"insert into {self.table_coin}(`id`,`name`,`symbol`,`categories`," \
                  f"`slug_cmc`,`fdv`,`vol_24h`,`spider_date`,`spider_time`, `supply`) values{value_sql};"
            # 存在则能插入成功
            try:
                self.rds.insert(sql)
                success_inserted_num += 1
            # 存在则插入失败
            except:
                logger.warning(f'插入失败：{sql}')
        return success_inserted_num

    def all_date_coin_vol(self, coin_id, name):
        """
        一共是6个月的时间跨度
        """
        time_couples = [
            {
                'timeStart':1705622400,
                'timeEnd': 1710892800,
            },
            {
                'timeStart': 1700438400,
                'timeEnd': 1705622400,
            },
            {
                'timeStart': 1695254400,
                'timeEnd': 1700438400,
            }
        ]
        total_inserted_success_num = 0
        # 单个代币180天的数据
        for time_couple in time_couples:
            timeStart = time_couple['timeStart']
            timeEnd = time_couple['timeEnd']
            # 生成历史数据API URL
            url = self.history_vol24_api.format(coin_id, timeStart, timeEnd)
            # 2个月内的数据
            data = self.req_one_datecouple_onecoin_vol24(url, name)
            # 入库
            if data:
                success_inserted_num = self.insert_coin_table(name, data)
                total_inserted_success_num += success_inserted_num
        # 统计实际入库了多少天的历史数据
        logger.info(f'历史vol24数据一共成功插入的天数 ({total_inserted_success_num}) ：{name} {coin_id}')

    def all_coins_vol24_180data(self):
        """
        所有代币最近半年的vol24 数据
        """
        # 遍历每一个币
        for name in self.jobs:
            matched_cmc = self.jobs[name]['matched_cmc']
            slug = matched_cmc['slug']
            # 请求HTML页面获取代币的ID
            coin_id = self.get_coin_id(slug)
            if not coin_id:
                logger.error(f'{slug} 无法获取到代币ID')
                # 将获取代币ID失败的代币slug加入redis队列
                self.redis_cli.sadd(self.failed_history_slugs, name)
                return
            self.all_date_coin_vol(coin_id, name)